draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw book
  ctx.fillStyle = '#663300';
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-50, 25, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-25);
  ctx.lineTo(W/2, H/2+25);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2-35, H/2+35);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2+35, H/2+35);
  ctx.stroke();

  // Draw wisdom words
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply Wisdom', W/2, H/2-120 + 50*Math.sin(t));

  // Draw lesson life applying
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson ' + Math.floor(1 + 8*Math.sin(t)), W/2, H/2-90);
  ctx.fillText('Life', W/2, H/2-60);
  ctx.fillText('Applying ' + Math.floor(7 + 6*Math.sin(t)), W/2, H/2-30);

  ctx.restore();
}
